test("uses compact defaults and opens a later bounded window without preceding events", () => {
	const content = jsonl(Array.from({ length: 60 }, (_, index) => ({
		type: "message",
		message: { role: "user", content: `event ${index + 1} ${"x".repeat(300)}` },
	})));

	const initial = parseCompactPiSessionEvents(content);
	assert.equal(initial.events.length, 24);
	assert.equal(initial.events[0].sequence, 1);
	assert.equal(initial.events.at(-1).sequence, 24);
	assert.equal(initial.events[0].text.length, 240);
	assert.equal(initial.nextStartSequence, 25);
	assert.equal(initial.truncated, true);

